AcceptanceCriteria.AC-ARCHIVE-PRESERVATION:
        Every pre-existing path under `.ngrace/changes/archive/` is byte-identical to base
        `c58e93f2e6f6a91b8bf5528edd3b29724652390c`, and the set of pre-existing archive bundle root
        directories is unchanged. The instrument reads the base commit's tracked blob bytes and
        compares them to the actual filesystem bytes of every protected path, so a byte edited under
        `--assume-unchanged` or `--skip-worktree` still fails; it separately inventories every actual
        file under the archive, including untracked and ignored additions, and compares archive root
        names by exact membership, not by a C-ID substring or line filter. It excludes exactly this
        bundle's own archive directory and its descendants, by exact path, with the reason that the
        close's own rename reddens the criterion it wrote. It compares bytes and identities only,
        never parses or executes archive contents, does not fabricate a baseline for empty nested
        `run/` directories, and deletes none. It fails closed on a missing base or a failed Git or
        read subprocess. No predecessor-arrival exclusion is present because this bundle supersedes
        nothing.
        git diff --exit-code c58e93f2e6f6a91b8bf5528edd3b29724652390c -- .ngrace/changes/archive ':(exclude).ngrace/changes/archive/C-REVIEW-CURRENT-BOUNDARY-1-217D3F0D' && bun -e 'const {spawnSync}=require("node:child_process");
const fs=require("node:fs");
const path=require("node:path");
const crypto=require("node:crypto");
const BASE="c58e93f2e6f6a91b8bf5528edd3b29724652390c";
const OWN="C-REVIEW-CURRENT-BOUNDARY-1-217D3F0D";
const ARCH=".ngrace/changes/archive";
function fail(msg){console.error("GUARD-A FAIL: "+msg);process.exit(1);}
function dep(cmd,args){const r=spawnSync(cmd,args,{encoding:"buffer"});if(r.error){fail("dependency error "+cmd+": "+r.error.message);}if(r.status!==0){fail("dependency exit "+r.status+" "+cmd+" "+args.join(" ")+" :: "+r.stderr.toString().trim());}return r.stdout;}
function contentOf(p){const st=fs.lstatSync(p);if(st.isSymbolicLink())return Buffer.from(fs.readlinkSync(p));if(!st.isFile())throw new Error("unsupported file type "+p);return fs.readFileSync(p);}
function blobSha(buf){return crypto.createHash("sha1").update(Buffer.concat([Buffer.from("blob "+buf.length+"\0"),buf])).digest("hex");}
const raw=dep("git",["ls-tree","-r","-z",BASE,"--",ARCH]).toString("utf8");
const base=new Map();
const baseRoots=new Set();
for(const rec of raw.split("\0")){if(rec.length===0)continue;const tab=rec.indexOf("\t");const meta=rec.slice(0,tab);const p=rec.slice(tab+1);base.set(p,meta.split(" ")[2]);const seg=p.slice(ARCH.length+1).split("/")[0];if(seg)baseRoots.add(seg);}
function isOwn(rel){return rel===OWN||rel.startsWith(OWN+"/");}
const bad=[];
for(const [p,sha] of base){if(!fs.existsSync(p)){bad.push("missing "+p);continue;}let b;try{b=contentOf(p);}catch(e){bad.push("unreadable "+p);continue;}if(blobSha(b)!==sha)bad.push("byte "+p);}
const actual=[];
function walk(d){for(const n of fs.readdirSync(d)){const p=path.join(d,n);if(p===ARCH+"/"+OWN)continue;const st=fs.lstatSync(p);if(st.isDirectory())walk(p);else actual.push(p);}}
walk(ARCH);
for(const p of actual){const rel=p.slice(ARCH.length+1);if(isOwn(rel))continue;if(!base.has(p))bad.push("extra "+p);}
const actualRoots=new Set();
for(const n of fs.readdirSync(ARCH)){if(isOwn(n))continue;actualRoots.add(n);}
for(const r of baseRoots)if(!actualRoots.has(r))bad.push("root-missing "+r);
for(const r of actualRoots)if(!baseRoots.has(r))bad.push("root-extra "+r);
if(bad.length){fail(bad.slice(0,30).join("; "));}
console.log("GUARD-A OK base="+base.size+" actual="+actual.length+" roots="+actualRoots.size);'

AcceptanceCriteria.AC-BOUNDED-WRITES:
        Relative to base `c58e93f2e6f6a91b8bf5528edd3b29724652390c`, the only tracked changes are the
        ten named implementation paths and this bundle's own active/archive lifecycle paths. The
        instrument checks staged changes and compares each protected path's Git type/executable mode and base blob bytes against its filesystem state,
        independently of `--assume-unchanged` or `--skip-worktree`, and fails on any changed,
        deleted, or newly tracked path outside the exact ten and the own active/archive directories;
        a persistent tracked candidate-lock path is not exempt and fails. It adds no general helper
        and no additional implementation path, and fails closed on a missing base or a failed Git or
        read subprocess.
        git diff --exit-code c58e93f2e6f6a91b8bf5528edd3b29724652390c -- . ':(exclude)src/review/core.ts' ':(exclude)src/review/catalog.ts' ':(exclude)src/review/core.test.ts' ':(exclude)src/verification/localize.test.ts' ':(exclude)src/gates/ledger.ts' ':(exclude)src/gates/core.test.ts' ':(exclude)skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)plugins/ngrace/skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)src/test-support/token-accounting.test.ts' ':(exclude)README.md' ':(exclude).ngrace/changes/active/C-REVIEW-CURRENT-BOUNDARY-1-217D3F0D' ':(exclude).ngrace/changes/archive/C-REVIEW-CURRENT-BOUNDARY-1-217D3F0D' && git diff --cached --exit-code c58e93f2e6f6a91b8bf5528edd3b29724652390c -- . ':(exclude)src/review/core.ts' ':(exclude)src/review/catalog.ts' ':(exclude)src/review/core.test.ts' ':(exclude)src/verification/localize.test.ts' ':(exclude)src/gates/ledger.ts' ':(exclude)src/gates/core.test.ts' ':(exclude)skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)plugins/ngrace/skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)src/test-support/token-accounting.test.ts' ':(exclude)README.md' ':(exclude).ngrace/changes/active/C-REVIEW-CURRENT-BOUNDARY-1-217D3F0D' ':(exclude).ngrace/changes/archive/C-REVIEW-CURRENT-BOUNDARY-1-217D3F0D' && bun -e 'const {spawnSync}=require("node:child_process");
const fs=require("node:fs");
const crypto=require("node:crypto");
const BASE="c58e93f2e6f6a91b8bf5528edd3b29724652390c";
const OWN="C-REVIEW-CURRENT-BOUNDARY-1-217D3F0D";
const ALLOWED=new Set(["src/review/core.ts","src/review/catalog.ts","src/review/core.test.ts","src/verification/localize.test.ts","src/gates/ledger.ts","src/gates/core.test.ts","skills/ngrace/ngrace-plan/SKILL.md","plugins/ngrace/skills/ngrace/ngrace-plan/SKILL.md","src/test-support/token-accounting.test.ts","README.md"]);
function fail(msg){console.error("GUARD-B FAIL: "+msg);process.exit(1);}
function dep(cmd,args){const r=spawnSync(cmd,args,{encoding:"buffer"});if(r.error){fail("dependency error "+cmd+": "+r.error.message);}if(r.status!==0){fail("dependency exit "+r.status+" "+cmd+" "+args.join(" ")+" :: "+r.stderr.toString().trim());}return r.stdout;}
function contentOf(p){const st=fs.lstatSync(p);if(st.isSymbolicLink())return Buffer.from(fs.readlinkSync(p));return fs.readFileSync(p);}
function blobSha(buf){return crypto.createHash("sha1").update(Buffer.concat([Buffer.from("blob "+buf.length+"\0"),buf])).digest("hex");}
function isOwn(p){const a=".ngrace/changes/active/"+OWN;const b=".ngrace/changes/archive/"+OWN;return p===a||p.startsWith(a+"/")||p===b||p.startsWith(b+"/");}
function allowed(p){return ALLOWED.has(p)||isOwn(p);}
const baseRaw=dep("git",["ls-tree","-r","-z",BASE]).toString("utf8");
const base=new Map();
for(const rec of baseRaw.split("\0")){if(rec.length===0)continue;const tab=rec.indexOf("\t");const meta=rec.slice(0,tab).split(" ");base.set(rec.slice(tab+1),{mode:meta[0],sha:meta[2]});}
const cur=dep("git",["ls-files","-z"]).toString("utf8").split("\0").filter(s=>s.length>0);
const curSet=new Set(cur);
const bad=[];
for(const [p,entry] of base){if(allowed(p))continue;if(!curSet.has(p)){bad.push("deleted "+p);continue;}let b;try{const st=fs.lstatSync(p);const mode=st.isSymbolicLink()?"120000":st.isFile()?((st.mode&0o100)?"100755":"100644"):"invalid";if(mode!==entry.mode){bad.push("mode/type "+p);continue;}b=contentOf(p);}catch(e){bad.push("unreadable "+p);continue;}if(blobSha(b)!==entry.sha)bad.push("byte "+p);}
for(const p of cur){if(allowed(p))continue;if(!base.has(p))bad.push("extra-tracked "+p);}
if(bad.length){fail(bad.slice(0,30).join("; "));}
console.log("GUARD-B OK tracked="+curSet.size);'
